<?php
require_once __DIR__ . '/bootstrap.php';
$conn=conecta(); $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$stmt=$conn->prepare('INSERT INTO entrada (fk_produto,data,quantidade,custo) VALUES (:produto,:data,:quantidade,:custo)');$stmt->execute([':produto'=>(int)post('produto'),':data'=>post('data')?:date('Y-m-d'),':quantidade'=>(int)post('quantidade'),':custo'=>(float)str_replace(',','.',post('custo'))]);header('Location: entradas.php');exit;}catch(Throwable $exception){$message=$exception->getMessage();}}
$products=$conn->query('SELECT id_produto,nome FROM produto WHERE (excluido IS FALSE OR excluido IS NULL) ORDER BY nome')->fetchAll(PDO::FETCH_ASSOC);
$entries=$conn->query('SELECT e.id_entrada,e.data,e.quantidade,e.custo,p.nome FROM entrada e JOIN produto p ON p.id_produto=e.fk_produto ORDER BY e.data DESC,e.id_entrada DESC')->fetchAll(PDO::FETCH_ASSOC);
adminHeader('Entradas');?><main class="admin-page"><h1>Entradas de estoque</h1><?php if($message):?><p class="admin-message admin-error"><?=e($message)?></p><?php endif;?><div class="admin-card"><form class="admin-form" method="post"><label>Produto<select name="produto" required><option value="">Selecione</option><?php foreach($products as $p):?><option value="<?=$p['id_produto']?>"><?=e($p['nome'])?></option><?php endforeach;?></select></label><label>Data<input type="date" name="data" value="<?=date('Y-m-d')?>" required></label><label>Quantidade<input type="number" min="1" name="quantidade" required></label><label>Custo unitário<input type="number" step="0.01" min="0" name="custo" required></label><button class="admin-button">Registrar entrada</button></form></div><table class="admin-table"><tr><th>ID</th><th>Data</th><th>Produto</th><th>Qtd.</th><th>Custo</th></tr><?php foreach($entries as $entry):?><tr><td><?=$entry['id_entrada']?></td><td><?=date('d/m/Y',strtotime($entry['data']))?></td><td><?=e($entry['nome'])?></td><td><?=$entry['quantidade']?></td><td>R$ <?=number_format((float)$entry['custo'],2,',','.')?></td></tr><?php endforeach;?></table></main><?php adminFooter();?>
